(function($, elementor) {
    $(window).on('elementor/frontend/init', function() {
        let moduleHandler = elementorModules.frontend.handlers.Base,
            VLP_Mobile_Menu;

        VLP_Mobile_Menu = moduleHandler.extend({
            getDefaultSettings() {
                return {
                    selectors: {
                        main: '.vl-widget-mobile-menu-main',
                        activeClass: 'vl-mobile-menu-active'
                    }
                }
            },

            getDefaultElements() {
                const {
                    main,
                    activeClass
                } = this.getSettings('selectors');

                return {
                    $main: this.$element.find(main),
                    $activeClass: activeClass
                }
            },

            bindEvents: function() {
                this._execute();
            },

            _execute: function() {
                let $id = this.getID(),
                    $main = this.elements.$main;

                if ($main.length) {
                    this._bindMobileMenuTrigger();
                    this._bindOverlayClick();
                    this._bindCloseClick();
                    this._bindMobileSubMenuTrigger();
                }
            },
            _bindMobileMenuTrigger() {
                let $activeClass = this.elements.$activeClass,
                    $menuEle = this.findElement(".vl-mobile-menu-nav-holder"),
                    $overLayEle = this.findElement(".vl-mobile-nav-overlay"),
                    $openerEle = this.findElement(".vl-mobile-nav-trigger");

                if ($openerEle.length) {
                    $($openerEle).on("click", function($e) {
                        $e.preventDefault();
                        $menuEle.toggleClass($activeClass);
                        $overLayEle.toggleClass($activeClass);
                    });
                }
            },
            _bindOverlayClick() {
                let _self = this,
                    $activeClass = _self.elements.$activeClass,
                    $menuEle = _self.findElement(".vl-mobile-menu-nav-holder"),
                    $overLayEle = _self.findElement(".vl-mobile-nav-overlay");

                if ($overLayEle.length) {
                    $($overLayEle).on("click", function($e) {
                        $e.preventDefault();

                        $menuEle.toggleClass($activeClass);
                        $overLayEle.toggleClass($activeClass);
                        _self.findElement("ul.sub-menu").addClass("sub-menu-hidden");
                        _self.findElement("li.vl-sub-menu-active").removeClass("vl-sub-menu-active");
                    });
                }
            },
            _bindCloseClick() {
                let _self = this,
                    $activeClass = _self.elements.$activeClass,
                    $closeEle = _self.findElement(".vl-mobile-nav-close-trigger"),
                    $menuEle = _self.findElement(".vl-mobile-menu-nav-holder"),
                    $overLayEle = _self.findElement(".vl-mobile-nav-overlay");

                if ($closeEle.length) {
                    $($closeEle).on("click", function($e) {
                        $e.preventDefault();
                        $menuEle.toggleClass($activeClass);
                        $overLayEle.toggleClass($activeClass);
                        _self.findElement("ul.sub-menu").addClass("sub-menu-hidden");
                        _self.findElement("li.vl-sub-menu-active").removeClass("vl-sub-menu-active");
                    });
                }
            },
            _bindMobileSubMenuTrigger() {
                let $subMenuOpenerEle = this.findElement(".vl-sub-menu-trigger");

                if ($subMenuOpenerEle.length) {
                    $($subMenuOpenerEle).on("click", function($e) {
                        $e.preventDefault();
                        $(this).toggleClass("vl-sub-menu-active");
                        $(this).next("ul.sub-menu").toggleClass("sub-menu-hidden");
                        $(this).parent("li.menu-item-has-children").toggleClass("vl-sub-menu-active");
                    });
                }
            },
        });

        elementorFrontend.elementsHandler.attachHandler('vlp-mobile-menu', VLP_Mobile_Menu);
    });
})(jQuery, window.elementorFrontend);